-- -> returns JSON (object or array)
SELECT metadata -> 'color' FROM products WHERE id = 1;  -- "red" (JSON string)

-- ->> returns TEXT
SELECT metadata ->> 'color' FROM products WHERE id = 1;  -- red (plain text)

-- Nested access
SELECT metadata -> 'storage' ->> 'type' FROM products WHERE id = 2;  -- SSD

-- Filter by JSON value
SELECT * FROM products WHERE metadata ->> 'color' = 'red';
SELECT * FROM products WHERE (metadata ->> 'ram_gb')::INTEGER > 8;

-- @> contains (most important for indexing)
SELECT * FROM products WHERE metadata @> '{"color": "red"}';
SELECT * FROM products WHERE metadata @> '{"tags": ["summer"]}';

-- ? key exists
SELECT * FROM products WHERE metadata ? 'brand';

-- Update a JSONB field
UPDATE products
  SET metadata = metadata || '{"price": 29.99}'
  WHERE id = 1;
-- jsonb_set for nested updates:
UPDATE products
  SET metadata = jsonb_set(metadata, '{storage, gb}', '1024')
  WHERE id = 2;

-- GIN index enables fast @> (contains) queries
CREATE INDEX idx_products_metadata ON products USING GIN (metadata);

-- This query will now use the GIN index:
SELECT * FROM products WHERE metadata @> '{"color": "red"}';

-- For specific key access (faster, smaller index)
CREATE INDEX idx_products_color ON products ((metadata ->> 'color'));
-- Supports: WHERE metadata ->> 'color' = 'red'
